using System.Windows; namespace CloudServer; public partial class UserDialog:Window { public string UserName=>UserBox.Text.Trim(); public string DisplayName=>NameBox.Text.Trim(); public string Password=>PasswordBox.Password; public long QuotaBytes{get;private set;} public UserDialog():this("", "", 0){} public UserDialog(string userName,string displayName,long quota){InitializeComponent();UserBox.Text=userName;NameBox.Text=displayName;if(quota<=0){UnlimitedBox.IsChecked=true;}else if(quota>=1099511627776L&&quota%1099511627776L==0){UnitBox.SelectedIndex=1;QuotaBox.Text=(quota/1099511627776L).ToString();}else{UnitBox.SelectedIndex=0;QuotaBox.Text=Math.Max(1,quota/1073741824L).ToString();}UnlimitedBox.Checked+=(_,__)=>Toggle();UnlimitedBox.Unchecked+=(_,__)=>Toggle();SaveButton.Click+=(_,__)=>Save();} void Toggle(){QuotaBox.IsEnabled=UnitBox.IsEnabled=UnlimitedBox.IsChecked!=true;} void Save(){if(string.IsNullOrWhiteSpace(UserName)){System.Windows.MessageBox.Show("Benutzername ist erforderlich.");return;}if(UnlimitedBox.IsChecked==true)QuotaBytes=0;else {if(!decimal.TryParse(QuotaBox.Text,out var q)||q<=0){System.Windows.MessageBox.Show("Bitte eine gültige Kapazität eingeben.");return;}decimal factor=UnitBox.SelectedIndex==1?1099511627776m:1073741824m;QuotaBytes=(long)Math.Min(q*factor,long.MaxValue);}DialogResult=true;} }